package com.personalassistant.companion;

import android.app.*;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.time.LocalDate;
import java.util.*;

/** One durable conversation. The relay accepts questions while the coach is offline. */
final class WorkoutCoach {
    final WorkoutScreen screen;final MainActivity a;final AppUi ui;
    WorkoutCoach(WorkoutScreen s){screen=s;a=s.a;ui=s.ui;}
    void open(JSONObject context,WorkoutLive live){open(context,live,"");}
    void open(JSONObject context,WorkoutLive live,String prefill){open(context,live,prefill,new JSONArray());}
    void open(JSONObject context,WorkoutLive live,String prefill,JSONArray photos){WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Coach");TextView state=ui.type("Checking…",13,18,500,0,ui.muted);state.setTag("coach_state");s.body.addView(state,WorkoutViews.gap(ui,10));LinearLayout items=ui.column();s.body.addView(items);
        LinearLayout bar=ui.row();bar.setPadding(ui.dp(12),ui.dp(6),ui.dp(12),ui.dp(10));EditText input=ui.field("Ask your coach",prefill);input.setTag("coach_input");input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES|InputType.TYPE_TEXT_FLAG_MULTI_LINE);bar.addView(input,new LinearLayout.LayoutParams(0,-2,1));ImageButton send=ui.iconButton("send","Send",null);bar.addView(send,new LinearLayout.LayoutParams(ui.dp(52),ui.dp(52)));s.root.addView(bar);
        Handler main=new Handler(Looper.getMainLooper());final String[] seen={""};Runnable[] poll=new Runnable[1];
        class ConversationPoll implements Runnable {
            String version="";boolean busy;int backoff;
            public void run(){
                main.removeCallbacks(this);if(!s.dialog.isShowing()||busy)return;
                if(!a.hasWindowFocus()){main.postDelayed(this,1000);return;}busy=true;String since=version;
                new Thread(()->{JSONObject r=null;try{r=(JSONObject)Cloud.call(a,"workout/trainer/conversation?limit=50"+(since.isEmpty()?"":"&since="+java.net.URLEncoder.encode(since,"UTF-8")+"&wait=10"),null,true);}catch(Exception ignored){}JSONObject got=r;
                    a.runOnUiThread(()->{busy=false;if(!s.dialog.isShowing())return;int delay=5000;
                        if(got==null){state.setText("No connection");state.setTextColor(ui.muted);backoff=Math.min(30000,backoff==0?2000:backoff*2);delay=backoff;}
                        else{backoff=0;JSONObject st=got.optJSONObject("status");boolean on=st!=null&&st.optBoolean("available");state.setText(on?"Online":"Offline");state.setTextColor(on?ui.success:ui.muted);String key=on+":"+got.optJSONArray("items");if(!key.equals(seen[0])){boolean tail=seen[0].isEmpty()||s.scroll.getScrollY()+s.scroll.getHeight()>=s.body.getHeight()-ui.dp(80);seen[0]=key;paint(items,got.optJSONArray("items"),live,poll[0],on);if(tail)s.scroll.post(()->s.scroll.fullScroll(View.FOCUS_DOWN));}version=got.optString("version","");if(!version.isEmpty())delay=0;}
                        main.postDelayed(this,delay);
                    });
                },"coach-conversation").start();
            }
        }
        poll[0]=new ConversationPoll();
        send.setOnClickListener(v->{String text=input.getText().toString().trim();if(text.isEmpty())return;send.setEnabled(false);String payloadKey=text+"\n"+context.toString()+"\n"+photos.toString();String previousKey=Cloud.prefs(a).getString("workout_coach_pending_key","");String id=payloadKey.equals(previousKey)?Cloud.prefs(a).getString("workout_coach_pending_id",WorkoutStore.id()):WorkoutStore.id();Cloud.prefs(a).edit().putString("workout_coach_pending_key",payloadKey).putString("workout_coach_pending_id",id).apply();new Thread(()->{String problem=null;boolean queued=false;try{String syncProblem=WorkoutStore.sync(a);if(!syncProblem.isEmpty())throw new java.io.IOException(syncProblem);JSONObject response=(JSONObject)Cloud.call(a,"workout/trainer/questions",new JSONObject().put("id",id).put("text",text).put("photos",photos).put("photo_approval",photos.length()>0).put("context",context),true);queued="queued".equals(response.optString("state"));}catch(Cloud.HttpError e){problem=e.status==409?"Couldn’t queue this message. Your draft is still here.":"Your server refused the question.";}catch(Exception e){problem="No connection. Your draft is still here. Tap Send when connected.";}String m=problem;boolean saved=queued;a.runOnUiThread(()->{send.setEnabled(true);if(m!=null){Toast.makeText(a,m,Toast.LENGTH_LONG).show();return;}if(saved)Toast.makeText(a,"Message queued. Check this Coach chat for the reply.",Toast.LENGTH_LONG).show();input.setText("");while(photos.length()>0)photos.remove(photos.length()-1);Cloud.prefs(a).edit().remove("workout_coach_pending_key").remove("workout_coach_pending_id").apply();main.removeCallbacks(poll[0]);poll[0].run();});}).start();});
        s.show();poll[0].run();}
    private void paint(LinearLayout items,JSONArray list,WorkoutLive live,Runnable poll,boolean online){items.removeAllViews();if(list==null||list.length()==0){items.addView(ui.detail(online?"Ask about a swap, fatigue, pain or your plan.":"The coach is offline. You can still send a message. The reply will appear in this chat when the coach is back."));return;}for(int i=0;i<list.length();i++){JSONObject q=list.optJSONObject(i);if(q==null)continue;JSONObject ctx=q.optJSONObject("context");if(ctx!=null&&("next_session_brief".equals(ctx.optString("purpose"))||"sprint_brief".equals(ctx.optString("purpose"))))continue;TextView mine=ui.type(q.optString("question"),14,20,500,0,ui.text);mine.setPadding(ui.dp(12),ui.dp(8),ui.dp(12),ui.dp(8));mine.setBackground(ui.outline(ui.accentSoft,14,0,0));LinearLayout.LayoutParams p=MainParts.params(ui,-1,-2,36,4,0,6);items.addView(mine,p);String st=q.optString("state"),partial=q.optString("partial_answer","");if("completed".equals(st)||"running".equals(st)&&!partial.isEmpty()){LinearLayout c=WorkoutViews.card(ui);c.addView(ui.type("completed".equals(st)?q.optString("answer"):partial,14,21,400,0,ui.text));if("completed".equals(st))proposals(c,q,live,poll);else c.addView(ui.small("Answering…"));items.addView(c,WorkoutViews.gap(ui,8));}else items.addView(ui.type("failed".equals(st)?"Your coach couldn't answer. Try again.":"queued".equals(st)?(online?"Queued. The reply will appear here.":"Queued. The reply will appear here when the coach is back online."):"Your coach is thinking…",13,18,500,0,"failed".equals(st)?ui.warning:ui.muted),WorkoutViews.gap(ui,8));}}
    /** Shows what each proposal would change next to what's there now; Apply takes them all, once. */
    private void proposals(LinearLayout c,JSONObject q,WorkoutLive live,Runnable poll){JSONArray list=q.optJSONArray("proposals");if(list==null||list.length()==0)return;boolean done=q.optInt("approved",0)!=0||q.optBoolean("approved");c.addView(ui.type("Proposed changes",12.5f,17,700,0,ui.accent),MainParts.params(ui,-1,-2,0,10,0,2));for(int i=0;i<list.length();i++){JSONObject p=list.optJSONObject(i);JSONObject now=WorkoutStore.data(a,p.optString("kind"),p.optString("id"));if("exercise".equals(p.optString("kind"))&&p.optJSONObject("data")!=null)c.addView(new WorkoutArt.Tile(ui,p.optJSONObject("data")),MainParts.params(ui,ui.dp(64),ui.dp(64),0,4,0,6));c.addView(ui.type("Before: "+describe(p.optString("kind"),now),12.5f,17,400,0,ui.muted));c.addView(ui.type(p.optBoolean("deleted")?"After: deleted."+("workout".equals(p.optString("kind"))?" Sprint progress and your next workout recalculate.":""):"After: "+describe(p.optString("kind"),p.optJSONObject("data")),12.5f,17,500,0,p.optBoolean("deleted")?ui.danger:ui.text),WorkoutViews.gap(ui,4));}
        if(done){c.addView(ui.type("Applied",13,18,600,0,ui.success));return;}Button apply=ui.quietButton("Apply changes",null);apply.setTag("coach_apply");apply.setOnClickListener(v->{if(live!=null&&!live.matchesSaved()){Toast.makeText(a,"Your workout changed since your coach saw it. Ask again before applying changes.",Toast.LENGTH_LONG).show();return;}apply.setEnabled(false);new Thread(()->{String problem=null;try{Cloud.call(a,"workout/trainer/"+q.optString("id")+"/approve",new JSONObject(),true);WorkoutStore.sync(a);}catch(Cloud.HttpError e){problem=e.status==409?"That changed since your coach answered. Ask again.":"Your server refused the change.";}catch(Exception e){problem="No connection. Nothing changed.";}String m=problem;a.runOnUiThread(()->{apply.setEnabled(true);if(m!=null){Toast.makeText(a,m,Toast.LENGTH_LONG).show();return;}if(live!=null)for(int i=0;i<list.length();i++){JSONObject p=list.optJSONObject(i);if(!"workout".equals(p.optString("kind"))||!p.optString("id").equals(live.d.optString("workout_id")))continue;if(p.optBoolean("deleted"))live.discard();else live.adopt(p.optJSONObject("data"));}screen.render();poll.run();});}).start();});c.addView(apply);}
    private String describe(String kind,JSONObject d){if(d==null)return "new "+kind;if("sprint".equals(kind)){JSONArray cycle=d.optJSONArray("cycle");return d.optString("name")+" · "+d.optString("phase")+" · "+d.optInt("target_sessions")+" workouts until "+d.optString("end")+(cycle==null?"":" · cycle of "+cycle.length());}if("template".equals(kind)){StringBuilder b=new StringBuilder(d.optString("name"));JSONArray ex=d.optJSONArray("exercises");for(int i=0;ex!=null&&i<ex.length();i++){JSONObject p=ex.optJSONObject(i);b.append(i==0?": ":", ").append(WorkoutStore.exerciseName(a,p.optString("exercise_id"))).append(' ').append(p.optInt("sets",1)).append('×').append(p.optInt("min_reps"));}return b.toString();}if(!"workout".equals(kind))return d.optString("name",kind);LinkedHashMap<String,StringBuilder> rows=new LinkedHashMap<>();JSONArray sets=d.optJSONArray("sets");for(int i=0;sets!=null&&i<sets.length();i++){JSONObject x=sets.optJSONObject(i);String n=WorkoutStore.exerciseName(a,x.optString("exercise_id"));if(!rows.containsKey(n))rows.put(n,new StringBuilder());StringBuilder b=rows.get(n);if(b.length()>0)b.append(", ");if(!x.isNull("distance_m")&&x.has("distance_m"))b.append(WorkoutUnits.distance(a,x.optDouble("distance_m"))).append(" in ").append(WorkoutViews.clock(x.optLong("seconds")));else{if(!x.isNull("weight_kg")&&x.has("weight_kg"))b.append(WorkoutUnits.load(a,x.optDouble("weight_kg"))).append(" × ");b.append(x.optInt("reps"));}if(!x.optBoolean("completed",true))b.append(" (open)");}StringBuilder out=new StringBuilder(d.optString("name"));LocalDate day=WorkoutStore.day(d);if(!day.equals(LocalDate.MIN))out.append(", ").append(day);for(Map.Entry<String,StringBuilder> e:rows.entrySet())out.append("\n").append(e.getKey()).append(": ").append(e.getValue());return out.toString();}
}
